mapper.select:
SELECT u.full_name, u.email, u.phone, u.role, b.branch_name, u.status, u.created_at FROM users u LEFT JOIN branches b ON b.branch_id = u.branch_id
u.branch_id = #{branchId}
ORDER BY u.created_at DESC NULLS LAST

SELECT s.service_code, s.service_name, s.service_type, s.estimated_time, b.branch_name, s.status FROM services s JOIN branches b ON b.branch_id = s.branch_id
s.branch_id = #{branchId}
ORDER BY s.service_code

SELECT t.ticket_number, t.customer_email, s.service_name, qm.machine_name AS queue_machine_name, b.branch_name, t.status, t.created_at FROM tickets t LEFT JOIN services s ON s.service_id = t.service_id LEFT JOIN queue_machines qm ON qm.queue_machine_id = t.queue_machine_id LEFT JOIN branches b ON b.branch_id = t.branch_id
t.branch_id = #{branchId}
ORDER BY t.created_at DESC NULLS LAST
